$root=dirname(__DIR__);require_once $root.'/scripts/lib/target-evidence-intake.php';require_once $root.'/app/Nexora/Foundation/Filesystem/AtomicFileWriter.php';$input='';foreach($argv as $arg)if(str_starts_with($arg,'--input='))$input=trim(substr($arg,8));if($input===''){fwrite(STDERR,"Usage: php scripts/n1-c6-ha-evidence-import.php --input=<directory-or-zip>\n");exit(2);}try{$found=nexoraDiscoverTargetEvidence($input);$path=$found['multi_node_ha']??null;if(!is_string($path)||!is_file($path))throw new RuntimeException('ha-evidence.json not found in C6 evidence input.');$data=nexoraEvidenceJson($path);if($data===null)throw new RuntimeException('HA evidence JSON is invalid.');$errors=nexoraValidateHaEvidence($root,$data);if($errors!==[])throw new RuntimeException(implode('; ',$errors));$writer=new App\Nexora\Foundation\Filesystem\AtomicFileWriter();$dest=$root.'/storage/app/nexora/certification/ha-evidence.json';$writer->ensureDirectory(dirname($dest));$writer->write($dest,(string)file_get_contents($path),0755,0640);fwrite(STDOUT,"[N1.0-C6 HA Evidence Import] PASS — exact-source multi-node HA evidence sealed.\n");}catch(Throwable $e){fwrite(STDERR,"[N1.0-C6 HA Evidence Import] FAIL — {$e->getMessage()}\n");exit(1);}
